scripts.count_inversions:
def solve(inputs: dict) -> float:
    values = inputs['VALUES']
    count = 0

    # Count all pairs (i, j) where i < j and values[i] > values[j]
    for i in range(len(values)):
        for j in range(i + 1, len(values)):
            if values[i] > values[j]:
                count += 1

    return float(count)

scripts.find_gcd:
def solve(inputs: dict) -> float:
    import math
    values = inputs['VALUES']

    # Compute GCD of all values using functools.reduce
    result = values[0]
    for val in values[1:]:
        result = math.gcd(result, val)

    return float(result)

scripts.factorial_mod:
def solve(inputs: dict) -> float:
    N = inputs['N']
    MOD = inputs['MOD']

    # Compute N! mod MOD
    result = 1
    for i in range(1, N + 1):
        result = (result * i) % MOD

    return float(result)

scripts.lcg_generator:
def solve(inputs: dict) -> float:
    X = inputs['SEED']
    A = inputs['A']
    B = inputs['B']
    M = inputs['M']
    K = inputs['K']

    # Run K rounds of X = (A * X + B) mod M
    for _ in range(K):
        X = (A * X + B) % M

    return float(X)

